{"file_text": ".settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.sidebar-title {
    padding: 0 1.5rem;
    margin: 0 0 1rem;
    font-size: 1.1rem;
    color: #333;
}

.sidebar-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.sidebar-nav li button {
    display: block;
    width: 100%;
    padding: 0.75rem 1.5rem;
    border: none;
    background: transparent;
    text-align: left;
    font-size: 0.95rem;
    color: #555;
    cursor: pointer;
    transition: background 0.15s, color 0.15s;
}

.sidebar-nav li button:hover {
    background: #e9ecef;
    color: #333;
}

.sidebar-nav li.active button {
    background: #e3f2fd;
    color: #1565c0;
    font-weight: 600;
    border-left: 3px solid #1565c0;
}

/* Main content */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #333;
}

/* Form elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #444;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

.form-group textarea {
    resize: vertical;
}

.form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

/* Buttons */
.btn-primary {
    padding: 0.5rem 1.25rem;
    background: #1565c0;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary:hover {
    background: #0d47a1;
}

.btn-secondary {
    padding: 0.5rem 1.25rem;
    background: #e0e0e0;
    color: #333;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-secondary:hover {
    background: #bdbdbd;
}

.btn-danger {
    padding: 0.4rem 0.75rem;
    background: #c62828;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-danger:hover {
    background: #b71c1c;
}

.btn-sm {
    padding: 0.3rem 0.6rem;
    font-size: 0.8rem;
}

/* Toast */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

.toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast.error {
    background: #ffebee;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

/* Avatar */
.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
}

.avatar-img {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #e0e0e0;
}

.avatar-url {
    font-size: 0.85rem;
    color: #666;
    word-break: break-all;
}

/* Toggles */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1.5rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

.toggle-label input[type="checkbox"] {
    width: 18px;
    height: 18px;
