+    width: 100%;
+    padding: 0.75rem 1rem;
+    border: none;
+    background: #f5f5f5;
+    text-align: left;
+    font-size: 0.95rem;
+    font-weight: 500;
+    cursor: pointer;
+}
+
+.panel-header:hover {
+    background: #eeeeee;
+}
+
+.panel-body {
+    padding: 1rem;
+    border-top: 1px solid #e0e0e0;
+}
+
+/* 2FA */
+.twofa-section {
+    margin-bottom: 1.5rem;
+}
+
+.twofa-status {
+    display: flex;
+    align-items: center;
+    gap: 1rem;
+}
+
+.status-indicator.enabled {
+    color: #2e7d32;
+    font-weight: 600;
+}
+
+.status-indicator.disabled {
+    color: #999;
+}
+
+.hint {
+    font-size: 0.85rem;
+    color: #666;
+    margin-top: 0.5rem;
+}
+
+/* Sessions table */
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    margin-top: 0.75rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.6rem 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.sessions-table th {
+    font-weight: 600;
+    color: #444;
+    background: #f9f9f9;
+}
+
+.current-badge {
+    font-size: 0.8rem;
+    background: #e3f2fd;
+    color: #1565c0;
+    padding: 0.2rem 0.5rem;
+    border-radius: 3px;
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.modal-dialog {
+    background: white;
+    padding: 1.5rem;
+    border-radius: 8px;
+    max-width: 400px;
+    width: 90%;
+}
+
+.modal-dialog h4 {
+    margin-top: 0;
+}
+
+.modal-actions {
+    margin-top: 1rem;
+    display: flex;
+    gap: 0.75rem;
+}
+
+/* Appearance Preview */
+.preview-area {
+    margin-top: 1.5rem;
+    padding: 1.5rem;
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    transition: all 0.2s;
+}
+
+.preview-area h4 {
+    margin-top: 0;
+}
+
+.preview-meta {
+    display: block;
+    margin-top: 0.75rem;
+    font-size: 0.8rem;
+    color: #888;
+}
+
+.preview-theme-light {
+    background: #ffffff;
+    color: #333;
+}
+
+.preview-theme-dark {
+    background: #1e1e2e;
+    color: #e0e0e0;
+}
+
+.preview-theme-dark .btn-primary {
+    background: #42a5f5;
+}
+
+.preview-theme-system {
+    background: #f5f5f5;
+    color: #333;
+}
+
+.preview-font-small {
+    font-size: 0.85rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.15rem;
+}
+
+.preview-compact {
+    padding: 0.75rem;
+    line-height: 1.3;
+}
+

